t=[[8,8,8,0,3,5,0,5,5,3,9,0,0,0,3,0,0,0,0],[8,0,8,8,3,5,5,5,5,3,0,0,9,9,3,4,4,0,4],[8,0,0,8,3,5,0,5,5,3,0,0,0,9,3,0,4,0,4],[0,0,8,8,3,0,0,5,5,3,9,9,9,0,3,0,4,4,0]]
for mode in ['majority','last','first']:
 out=[]
 for row in t:
  panels=[row[s:s+4] for s in (0,5,10,15)]
  o=[]
  for c in range(4):
   v=[p[c] for p in panels]
   if mode=='majority':
    from collections import Counter
    o.append(Counter(v).most_common(1)[0][0])
   elif mode=='last':o.append(next((x for x in v[::-1] if x),0))
   else:o.append(next((x for x in v if x),0))
  out.append(o)
 print(mode,out)
